<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import FinanceSubnav from'../components/FinanceSubnav.vue';import{useFinanceStore}from'../runtime/finance-store';import type{FundAccountType,FinanceEntityStatus}from'../types';import'./finance-views.css'
const store=useFinanceStore(),route=useRoute(),router=useRouter(),id=String(route.params.accountId??'');const form=reactive({name:'',type:'cash'as FundAccountType,status:'enabled'as FinanceEntityStatus,openingMonth:'2026-08',openingBalance:'0.00'}),message=ref(''),existingUpdatedAt=ref<string>();function cents(value:string){if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error('期初余额必须是非负金额，最多两位小数');const result=Math.round(Number(value)*100);if(!Number.isSafeInteger(result))throw new Error('期初余额超出安全范围');return result}async function submit(){message.value='';try{await store.saveAccount({requestId:crypto.randomUUID(),accountId:id||undefined,expectedUpdatedAt:existingUpdatedAt.value,draft:{name:form.name,type:form.type,status:form.status,openingMonth:form.openingMonth,openingBalanceCents:cents(form.openingBalance)}});await router.push('/finance/accounts')}catch(caught){message.value=caught instanceof Error?caught.message:'保存失败'}}onMounted(async()=>{if(!id)return;await store.loadAccounts();const found=store.accountDraft(id);if(!found){message.value='资金账户不存在';return}Object.assign(form,{name:found.draft.name,type:found.draft.type,status:found.draft.status,openingMonth:found.draft.openingMonth,openingBalance:(found.draft.openingBalanceCents/100).toFixed(2)});existingUpdatedAt.value=found.account.updatedAt})
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>{{id?'编辑':'新增'}}资金账户</h1><p>期初资料在已有流水或结转后锁定；账户只允许停用，不物理删除。</p></div></header><FinanceSubnav/><p v-if="message" class="finance-warning">{{message}}</p><form class="finance-panel finance-form" @submit.prevent="submit"><label>账户名称<input v-model.trim="form.name" maxlength="80" required></label><label>账户类型<select v-model="form.type"><option value="cash">现金</option><option value="bank">银行账户</option><option value="wechat">微信</option><option value="alipay">支付宝</option></select></label><label>启用月份<input v-model="form.openingMonth" type="month" min="2026-07" max="2026-08" required></label><label>首期期初余额<input v-model="form.openingBalance" inputmode="decimal" required></label><label>状态<select v-model="form.status"><option value="enabled">启用</option><option value="disabled">停用</option></select></label><p class="wide">已有流水或结转后，账户类型、启用月份和期初余额不可直接更改；后续更正等待 FIN-004 可追溯调整单。</p><div class="finance-actions"><button class="fin-button" type="button" @click="router.back()">取消</button><button class="fin-button primary" :disabled="store.saving">{{store.saving?'保存中…':'保存'}}</button></div></form></section></template>
